<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {StageRenderer} from '../training/renderer.js';
import {DemandLoop} from '../training/demand-loop.mjs';
import {fixtures,DEFAULT_STAGE,template,clone,blend,validate} from './state.mjs';
import {initPlatform,windowInfo,read,save} from './platform.mjs';
const data=ref(template()),tab=ref('lights'),zone=ref('front'),selected=ref([]),objectId=ref('a'),status=ref(''),ready=ref(false),playing=ref(false),active=ref(-1),fog=ref(false),orbit=ref(false),flat=ref(false),level=ref(70),color=ref('#ffdbab'),pan=ref(0),tilt=ref(0),autoOn=ref(true),autoLevel=ref(70),host=ref(),diagram=ref(),quality=ref('auto');
const zones=[['front','面光'],['ear-left','左耳光'],['ear-right','右耳光'],['side-left','左侧光'],['side-right','右侧光'],['top-1','顶光一'],['top-2','顶光二'],['top-3','顶光三'],['top-4','顶光四'],['top-5','顶光五'],['rear','彩灯'],['moving','摇头灯']];
const visible=computed(()=>fixtures.filter(f=>zone.value==='moving'?f.training.kind==='moving':f.training.zone===zone.value));
const object=computed(()=>data.value.current.objects.find(o=>o.id===objectId.value));
let renderer,loop,transition,last=0,hold=0,slow=0,saveTimer,disposed=false;
function notice(s){status.value=s}
function invalidate(){loop?.invalidate()}
function sync(){if(!renderer||flat.value)return;const f=data.value.current;fixtures.forEach((fixture,i)=>{const l=f.lights[i];fixture.training.baseColor=l.color;fixture._3DModel={intensity:l.level,rgb:[1,3,5].map(k=>parseInt(l.color.slice(k,k+2),16)/255),pan:l.pan,tilt:l.tilt,shutter:1}});renderer.syncStage(f.objects,f.curtains);renderer.update(fixtures,{fog:fog.value,master:1,blackout:false,repair:true},selected.value,false);}
function draw2d(){const c=diagram.value;if(!c)return;const w=c.clientWidth,h=c.clientHeight;if(!w||!h)return;c.width=w*1.5;c.height=h*1.5;const x=c.getContext('2d');x.scale(1.5,1.5);x.fillStyle='#101416';x.fillRect(0,0,w,h);const scale=Math.min((w-32)/21,(h-45)/15),ox=(w-21*scale)/2,oy=12;const frame=data.value.current;x.fillStyle='#39342a';x.fillRect(ox,oy,21*scale,15*scale);x.save();x.beginPath();x.rect(ox,oy,21*scale,15*scale);x.clip();frame.lights.forEach((l,i)=>{if(!l.level)return;const f=fixtures[i],tx=ox+(f.training.target.x+10.5+Math.sin(l.pan*Math.PI/180)*3)*scale,ty=oy+(15-f.training.target.y)*scale;const g=x.createRadialGradient(tx,ty,0,tx,ty,scale*3);g.addColorStop(0,l.color+'88');g.addColorStop(1,l.color+'00');x.globalAlpha=l.level;x.fillStyle=g;x.fillRect(ox,oy,21*scale,15*scale)});x.globalAlpha=1;frame.curtains.forEach(c=>{x.fillStyle='#7c293f';const a=c.amount??(c.closed?1:0),cw=(.7+9.8*a)*scale;x.fillRect(ox,oy+(15-c.y)*scale,cw,5);x.fillRect(ox+(21*scale)-cw,oy+(15-c.y)*scale,cw,5)});frame.objects.forEach(o=>{const px=ox+(o.x+10.5)*scale,py=oy+(15-o.y)*scale;x.fillStyle=o.id===objectId.value?'#ffd88a':'#e8ddc2';x.fillRect(px-5,py-5,o.kind==='table'?20:10,10);x.font='11px sans-serif';x.fillText(o.name,px-15,py+20)});x.restore();x.fillStyle='#bab6a9';x.fillText('观众席',w/2-20,h-10);}
function draw(now){if(disposed)return;const dt=last?now-last:0;last=now;if(transition){transition.elapsed+=dt;const t=Math.min(1,transition.elapsed/transition.duration);data.value.current=blend(transition.from,transition.to,t*t*(3-2*t));if(t===1){transition=null;hold=0;}}else if(playing.value){hold+=dt;if(hold>=2000){if(active.value>=data.value.cues.length-1)stop();else go(active.value+1,true)}}const start=performance.now();if(flat.value)draw2d();else {sync();renderer?.advanceOrbit(now);renderer?.render()}const cost=performance.now()-start;if((playing.value||orbit.value)&&cost>70)slow++;else slow=Math.max(0,slow-1);if(slow>60){slow=0;if(quality.value!=='low'){quality.value='low';renderer?.setQuality('low');fog.value=false;}else fallback('已切换平面视图');}}
function stop(){playing.value=false;transition=null;hold=0;last=0;invalidate()}
function edit(){stop();invalidate()}
function select(id){selected.value=[id];const l=data.value.current.lights[id];level.value=Math.round(l.level*100);color.value=l.color;pan.value=l.pan;tilt.value=l.tilt;if(autoOn.value){l.level=autoLevel.value/100;level.value=autoLevel.value;}edit()}
function group(z){zone.value=z;selected.value=visible.value.map(f=>f.id);const l=data.value.current.lights[selected.value[0]];if(l){level.value=Math.round(l.level*100);color.value=l.color;pan.value=l.pan;tilt.value=l.tilt}if(autoOn.value)selected.value.forEach(i=>data.value.current.lights[i].level=autoLevel.value/100);edit()}
function change(){for(const i of selected.value)Object.assign(data.value.current.lights[i],{level:level.value/100,color:color.value,pan:pan.value,tilt:tilt.value});edit()}
function all(v){data.value.current.lights.forEach(l=>l.level=v);edit()}
function go(i,keep=false){if(!keep)stop();const c=data.value.cues[i];if(!c)return;active.value=i;transition={from:clone(data.value.current),to:clone(c.frame),duration:c.seconds*1000,elapsed:0};last=0;invalidate()}
function play(){stop();playing.value=true;go(0,true)}
function capture(){stop();if(data.value.cues.length>=60)return notice('最多保存 60 个场景');data.value.cues.push({name:'场景 '+(data.value.cues.length+1),seconds:3,hold:2,frame:clone(data.value.current)});persist()}
async function persist(){try{await save(data.value);notice('已保存')}catch(e){notice(e.message||'保存失败')}}
function reset(){stop();data.value=template();fog.value=false;selected.value=[];active.value=-1;renderer?.view('front');invalidate();persist()}
function curtain(i){stop();const to=clone(data.value.current),c=to.curtains[i];c.closed=!c.closed;c.amount=c.closed?1:0;transition={from:clone(data.value.current),to,duration:1800,elapsed:0};invalidate()}
function add(kind){if(data.value.current.objects.length>=24)return notice('最多放置 24 个对象');const id='o'+Date.now();data.value.current.objects.push({id,kind,name:{actor:'演员',chair:'椅子',table:'桌子',block:'方台'}[kind],x:0,y:5,rotation:0});objectId.value=id;edit()}
function fallback(message){flat.value=true;orbit.value=false;if(renderer){renderer.dispose();renderer=null}notice(message);invalidate()}
function visibility(){if(document.hidden){loop?.setVisible(false);renderer?.asyncLighting?.worker.terminate();}else {last=0;renderer?.asyncLighting?.restart();windowInfo();loop?.setVisible(true);invalidate()}}
onMounted(async()=>{await initPlatform();try{const saved=await read();if(saved)data.value=validate(saved)}catch{notice('读取存档失败，当前显示模板')}if(disposed)return;loop=new DemandLoop({draw,active:()=>!!transition||playing.value||orbit.value});try{renderer=new StageRenderer(host.value,id=>{tab.value='lights';select(id)},invalidate);renderer.build(DEFAULT_STAGE,data.value.current.objects,fixtures,data.value.current.curtains);renderer.enableAsyncLighting();renderer.onOrbitChange=v=>{orbit.value=v};renderer.view('front');renderer.onObjectSelect=id=>{objectId.value=id;tab.value='props'};renderer.onObjectMove=(id,x,y)=>{const o=data.value.current.objects.find(o=>o.id===id);if(o){o.x=x;o.y=y;edit()}};renderer.renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();fallback('图形暂不可用，已切换平面视图')});renderer.onError=()=>fallback('已切换平面视图');}catch{fallback('当前使用平面视图')}ready.value=true;invalidate();document.addEventListener('visibilitychange',visibility);window.addEventListener('resize',invalidate)});
onBeforeUnmount(()=>{disposed=true;clearTimeout(saveTimer);loop?.dispose();renderer?.dispose();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('resize',invalidate)});
</script>
<template>
<div class="tool">
<header><div class="brand"><b>◈ 光场</b><span>灯光排练室</span></div><button @click="persist">保存</button></header>
<main :class="{pending:!ready}" :aria-busy="!ready">
<section class="stage">
<div class="stage-actions"><select v-model="quality" aria-label="画质" @change="renderer?.setQuality(quality);invalidate()"><option value="auto">清晰</option><option value="high">精细</option><option value="low">轻量</option></select><button @click="all(1)">灯光全开</button><button @click="all(0)">灯光全关</button></div>
<div ref="host" class="viewport" v-show="!flat"></div><canvas v-show="flat" ref="diagram" class="viewport" aria-label="舞台平面图"></canvas>
<div class="view-actions"><button @click="renderer?.view('front');invalidate()">正视</button><button @click="renderer?.view('top');invalidate()">俯视</button><button :aria-pressed="orbit" :disabled="flat" @click="orbit=!orbit;renderer?.setOrbit(orbit);invalidate()">环绕</button><label><input type="checkbox" v-model="fog" :disabled="flat" @change="invalidate">空气光束</label></div>
</section>
<section class="desk">
<nav><button v-for="t in [['lights','调灯'],['props','布景'],['cues','场景']]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></nav>
<div class="panel" v-show="tab==='lights'">
<div class="row"><h2>灯位分区</h2><label><input type="checkbox" v-model="autoOn">选中即亮</label></div><label class="slider">试灯亮度 <input aria-label="试灯亮度" type="range" min="0" max="100" v-model.number="autoLevel" @input="if(autoOn){selected.forEach(i=>data.current.lights[i].level=autoLevel/100);level=autoLevel;edit()}"><output>{{autoLevel}}%</output></label>
<div class="zones"><button v-for="z in zones" :key="z[0]" :class="{active:zone===z[0]}" @click="group(z[0])">{{z[1]}}</button></div>
<div class="lamps"><button v-for="f in visible" :key="f.id" :class="{active:selected.includes(f.id)}" @click="select(f.id)">{{f.training.kind==='moving'?'M':'L'}}{{f.training.number}}</button></div>
<template v-if="selected.length"><h2>已选 {{selected.length}} 盏灯</h2><label class="slider">亮度<input aria-label="亮度" type="range" min="0" max="100" v-model.number="level" @input="change"><output>{{level}}%</output></label><div class="palette"><button v-for="c in ['#fff4dc','#ffbe68','#ff657f','#da6fff','#688fff','#58dbff','#78efbd']" :key="c" :style="{background:c}" :aria-label="'颜色 '+c" @click="color=c;change()"></button><input aria-label="自选颜色" type="color" v-model="color" @input="change"></div><template v-if="selected.some(i=>fixtures[i].training.kind==='moving')"><label class="slider">水平<input aria-label="水平转向" type="range" min="-180" max="180" v-model.number="pan" @input="change"><output>{{pan}}°</output></label><label class="slider">俯仰<input aria-label="垂直转向" type="range" min="-90" max="90" v-model.number="tilt" @input="change"><output>{{tilt}}°</output></label></template></template>
</div>
<div class="panel" v-show="tab==='props'"><h2>四道布幕</h2><div class="zones"><button v-for="(c,i) in data.current.curtains" :key="c.id" @click="curtain(i)">{{c.name}} · {{c.closed?'打开':'关闭'}}</button></div><h2>演员与道具</h2><div class="zones"><button @click="add('actor')">＋演员</button><button @click="add('chair')">＋椅子</button><button @click="add('table')">＋桌子</button><button @click="add('block')">＋方台</button></div><select aria-label="选择道具" v-model="objectId"><option v-for="o in data.current.objects" :key="o.id" :value="o.id">{{o.name}}</option></select><template v-if="object"><label class="slider">横向<input aria-label="横向位置" type="range" min="-9" max="9" step=".1" v-model.number="object.x" @input="edit"><output>{{object.x.toFixed(1)}}</output></label><label class="slider">纵深<input aria-label="纵向位置" type="range" min="1" max="14" step=".1" v-model.number="object.y" @input="edit"><output>{{object.y.toFixed(1)}}</output></label><label class="slider">旋转<input aria-label="道具旋转" type="range" min="0" max="360" v-model.number="object.rotation" @input="edit"></label><button @click="data.current.objects=data.current.objects.filter(o=>o.id!==objectId);edit()">删除所选道具</button></template></div>
<div class="panel" v-show="tab==='cues'"><div class="row transport"><button class="primary" @click="playing?stop():play()">{{playing?'停止':'播放'}}</button><span>{{active<0?'场景编排':data.cues[active]?.name}}</span></div><div class="row edits"><button @click="reset">重置为模板场景</button><button @click="capture">＋新增当前场景</button></div><article v-for="(c,i) in data.cues" :key="i" :class="{current:i===active}"><div class="row"><span class="number">{{String(i+1).padStart(2,'0')}}</span><input :aria-label="'场景名称 '+(i+1)" v-model="c.name" maxlength="30"><button @click="go(i)">调用</button></div><div class="row"><label>渐变 <input :aria-label="'渐变 '+(i+1)" type="number" min=".2" max="30" step=".5" v-model.number="c.seconds" @change="c.seconds=Math.max(.2,Math.min(30,Number(c.seconds)||3))"> 秒</label><button @click="c.frame=clone(data.current);notice('已更新场景')">更新</button><button :disabled="i===0" @click="stop();data.cues.splice(i-1,0,data.cues.splice(i,1)[0]);active=-1">↑</button><button :aria-label="'删除场景 '+(i+1)" @click="stop();data.cues.splice(i,1);active=-1">×</button></div></article></div>
</section>
</main><div v-if="status" class="status" role="status" @click="status=''">{{status}} <button aria-label="关闭状态" @click="status=''">×</button></div><div v-if="!ready" class="loading">正在准备舞台…</div>
</div>
</template>
